def universal_scraper(url, parse_content=None, output_format=None, user_agent_type=None, target_domain=None, geo=None, locale=None, pagination_page=None, pagination_pages=None, priority=None, scheduled_at=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    period = datetime.datetime.utcnow().strftime("%Y%m")

    def _log_usage(workspace_id, api_key_id, job_id, tool, units, unit_type, status):
        usage = _load("usage_ledger.json")
        rid = "ul_" + uuid.uuid4().hex
        row = {
            "id": rid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": job_id,
            "tool": tool,
            "units": int(units),
            "unit_type": unit_type,
            "period_yyyymm": period,
            "created_at": now,
            "updated_at": now
        }
        usage.append(row)
        _save("usage_ledger.json", usage)
        return row

    def _resolve_auth():
        # No explicit credential parameter exists; pick a working active key whose workspace is active.
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        keys = _load("api_keys.json")
        for k in keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            return ws, k
        return None, None

    def _validate():
        if not isinstance(url, str) or not url.strip():
            return _err("VALIDATION_ERROR", "url must be a non-empty string", field="url")
        if parse_content is None:
            return _err("VALIDATION_ERROR", "parse_content is required", field="parse_content")
        if not isinstance(parse_content, bool):
            return _err("VALIDATION_ERROR", "parse_content must be a boolean", field="parse_content")
        if output_format is not None:
            if not isinstance(output_format, str) or output_format not in ("json", "html", "text", "csv"):
                return _err("VALIDATION_ERROR", "output_format must be one of: json, html, text, csv", field="output_format")
        if user_agent_type is not None:
            if not isinstance(user_agent_type, str) or user_agent_type not in ("desktop", "mobile", "tablet", "bot", "custom"):
                return _err("VALIDATION_ERROR", "user_agent_type must be one of: desktop, mobile, tablet, bot, custom", field="user_agent_type")
        for nm, v in (("target_domain", target_domain), ("geo", geo), ("locale", locale), ("idempotency_key", idempotency_key)):
            if v is not None and (not isinstance(v, str)):
                return _err("VALIDATION_ERROR", f"{nm} must be a string", field=nm)
        if pagination_page is not None:
            if not isinstance(pagination_page, int) or pagination_page < 1:
                return _err("VALIDATION_ERROR", "pagination_page must be an integer >= 1", field="pagination_page")
        if pagination_pages is not None:
            if not isinstance(pagination_pages, int) or not (1 <= pagination_pages <= 50):
                return _err("VALIDATION_ERROR", "pagination_pages must be an integer between 1 and 50", field="pagination_pages")
        if priority is not None:
            if not isinstance(priority, int) or not (0 <= priority <= 100):
                return _err("VALIDATION_ERROR", "priority must be an integer between 0 and 100", field="priority")
        if scheduled_at is not None:
            if not isinstance(scheduled_at, str):
                return _err("VALIDATION_ERROR", "scheduled_at must be an RFC3339 date-time string", field="scheduled_at")
            try:
                s = scheduled_at
                if s.endswith("Z"):
                    datetime.datetime.fromisoformat(s[:-1])
                else:
                    datetime.datetime.fromisoformat(s.replace("Z", ""))
            except ValueError:
                return _err("VALIDATION_ERROR", "scheduled_at must be an RFC3339 date-time string", field="scheduled_at")
        return None

    verr = _validate()
    if verr:
        # Cannot write usage without auth context; return validation error.
        return verr

    ws, key = _resolve_auth()
    if not ws or not key:
        return _err("UNAUTHORIZED", "No active API key with an active workspace is available to authenticate this request")

    # Record the request itself as 1 request unit (even if later rejected by quota).
    _log_usage(ws["id"], key["id"], None, "universal_scraper", 1, "request", "attempt")

    # Quota enforcement (job quota + request quota in current period)
    usage = _load("usage_ledger.json")
    jobs = _load("scrape_jobs.json")

    ws_id = ws["id"]
    monthly_job_quota = int(ws.get("monthly_job_quota", 0))
    monthly_request_quota = int(ws.get("monthly_request_quota", 0))

    jobs_this_period = 0
    for j in jobs:
        if isinstance(j, dict) and j.get("workspace_id") == ws_id:
            ca = j.get("created_at")
            if isinstance(ca, str) and len(ca) >= 7:
                try:
                    dt = ca.replace("Z", "")
                    yyyymm = dt[0:4] + dt[5:7]
                    if yyyymm == period:
                        jobs_this_period += 1
                except Exception:
                    pass

    requests_units_this_period = 0
    for u in usage:
        if not isinstance(u, dict):
            continue
        if u.get("workspace_id") != ws_id:
            continue
        if u.get("period_yyyymm") != period:
            continue
        if u.get("unit_type") == "request":
            try:
                requests_units_this_period += int(u.get("units", 0))
            except Exception:
                pass

    if monthly_job_quota <= 0:
        _log_usage(ws_id, key["id"], None, "universal_scraper", 0, "job", "rejected")
        return _err("QUOTA_EXCEEDED", "Monthly job quota exceeded for workspace", period_yyyymm=period)

    if jobs_this_period >= monthly_job_quota:
        _log_usage(ws_id, key["id"], None, "universal_scraper", 0, "job", "rejected")
        return _err("QUOTA_EXCEEDED", "Monthly job quota exceeded for workspace", period_yyyymm=period)

    if monthly_request_quota >= 0 and requests_units_this_period > monthly_request_quota:
        _log_usage(ws_id, key["id"], None, "universal_scraper", 0, "job", "rejected")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for workspace", period_yyyymm=period)

    # Idempotency
    if idempotency_key is not None:
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("workspace_id") == ws_id and j.get("idempotency_key") == idempotency_key:
                # Successful auth; touch key last_used_at
                keys = _load("api_keys.json")
                changed = False
                for kk in keys:
                    if isinstance(kk, dict) and kk.get("id") == key["id"]:
                        kk["last_used_at"] = now
                        kk["updated_at"] = now
                        changed = True
                        break
                if changed:
                    _save("api_keys.json", keys)
                _log_usage(ws_id, key["id"], j.get("id"), "universal_scraper", 0, "job", "idempotent_hit")
                return {"job": j, "idempotent": True}

    # Normalize inputs and compute fingerprint
    norm = {
        "url": url.strip(),
        "parse_content": parse_content,
        "output_format": output_format or "json",
        "user_agent_type": user_agent_type,
        "target_domain": target_domain,
        "geo": geo or ws.get("default_geo"),
        "locale": locale or ws.get("default_locale"),
        "pagination_page": pagination_page,
        "pagination_pages": pagination_pages
    }
    # universal requires at least one of input_url or input_query after normalization; here input_url always present.
    input_url = norm["url"]
    input_query = None

    fp_src = json.dumps({"tool": "universal_scraper", "input": norm}, sort_keys=True, ensure_ascii=False)
    request_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    # Create job
    job_id = "job_" + uuid.uuid4().hex
    prio = int(priority) if priority is not None else 50
    job = {
        "id": job_id,
        "workspace_id": ws_id,
        "api_key_id": key["id"],
        "tool": "universal_scraper",
        "status": "queued",
        "priority": prio,
        "scheduled_at": scheduled_at,
        "started_at": None,
        "finished_at": None,
        "idempotency_key": idempotency_key,
        "request_fingerprint": request_fingerprint,
        "input": norm,
        "input_url": input_url,
        "input_query": input_query,
        "target_domain": target_domain,
        "geo": norm["geo"],
        "locale": norm["locale"],
        "user_agent_type": user_agent_type,
        "pagination_page": pagination_page,
        "pagination_pages": pagination_pages,
        "output_format": norm["output_format"],
        "parse_content": parse_content,
        "amazon_category_id": None,
        "amazon_merchant_id": None,
        "amazon_currency": None,
        "amazon_asin": None,
        "amazon_auto_select_variant": None,
        "attempt": 1,
        "max_attempts": 3,
        "error_code": None,
        "error_message": None,
        "billable_units": 0,
        "created_at": now,
        "updated_at": now
    }

    jobs.append(job)
    _save("scrape_jobs.json", jobs)

    # Job unit usage (creation)
    _log_usage(ws_id, key["id"], job_id, "universal_scraper", 1, "job", "accepted")

    # Touch key last_used_at
    keys = _load("api_keys.json")
    for kk in keys:
        if isinstance(kk, dict) and kk.get("id") == key["id"]:
            kk["last_used_at"] = now
            kk["updated_at"] = now
            break
    _save("api_keys.json", keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {"job": job, "idempotent": False, "latency_ms": latency_ms}

def google_search_scraper(query, parse_content=None, output_format=None, user_agent_type=None, target_domain=None, geo=None, locale=None, pagination_page=None, pagination_pages=None, priority=None, scheduled_at=None, idempotency_key=None, **_extra):
