            if v is not None and (not isinstance(v, str)):
                return _err("VALIDATION_ERROR", f"{nm} must be a string", field=nm)
        if pagination_page is not None:
            if not isinstance(pagination_page, int) or pagination_page < 1:
                return _err("VALIDATION_ERROR", "pagination_page must be an integer >= 1", field="pagination_page")
        if pagination_pages is not None:
            if not isinstance(pagination_pages, int) or not (1 <= pagination_pages <= 50):
                return _err("VALIDATION_ERROR", "pagination_pages must be an integer between 1 and 50", field="pagination_pages")
        if priority is not None:
            if not isinstance(priority, int) or not (0 <= priority <= 100):
                return _err("VALIDATION_ERROR", "priority must be an integer between 0 and 100", field="priority")
