        "amazon_auto_select_variant": None,
        "attempt": 1,
        "max_attempts": 3,
        "error_code": None,
        "error_message": None,
        "billable_units": 0,
        "created_at": now,
        "updated_at": now
    }

    jobs.append(job)
    _save("scrape_jobs.json", jobs)
    _log_usage(ws_id, key["id"], job_id, "google_search_scraper", 1, "job", "accepted")

    keys = _load("api_keys.json")
