def get_identity(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    period = now.strftime("%Y%m")
    endpoint = "get_identity"

    def _log(status, workspace_id=None, api_key_id=None, job_id=None, tool=None, units=1, unit_type="request"):
        ledger = _load("usage_ledger.json")
        lid = "ul_" + now.strftime("%Y%m%d%H%M%S") + "_" + str(len(ledger) + 1)
        row = {
            "id": lid,
            "workspace_id": workspace_id if workspace_id is not None else "unknown",
            "api_key_id": api_key_id,
            "job_id": job_id,
            "tool": tool,
            "units": int(units) if isinstance(units, int) and units >= 0 else 1,
            "unit_type": unit_type,
            "period_yyyymm": period,
            "created_at": now_iso,
            "updated_at": now_iso,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        ledger.append(row)
        _save("usage_ledger.json", ledger)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", workspace_id="unknown", api_key_id=None)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    # Authenticate: match by id or client-visible key (stored as key_hash)
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break

    if not key_row:
        _log("error", workspace_id="unknown", api_key_id=None)
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        _log("error", workspace_id=key_row.get("workspace_id") or "unknown", api_key_id=key_row.get("id"))
        return _err("UNAUTHORIZED", "API key is not active")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws:
        _log("error", workspace_id=key_row.get("workspace_id") or "unknown", api_key_id=key_row.get("id"))
        return _err("UNAUTHORIZED", "Workspace not found for API key")

    if ws.get("status") != "active":
        _log("error", workspace_id=ws.get("id"), api_key_id=key_row.get("id"))
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Update last_used_at on successful auth
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # Compute usage for current period
    ledger = _load("usage_ledger.json")
    jobs = _load("scrape_jobs.json")

    used_request_units = 0
    used_job_events = 0
    for r in ledger:
        if r.get("workspace_id") == ws.get("id") and r.get("period_yyyymm") == period:
            if r.get("unit_type") == "request":
                u = r.get("units")
                if isinstance(u, int) and u >= 0:
                    used_request_units += u
            if r.get("unit_type") == "job":
                u = r.get("units")
                if isinstance(u, int) and u >= 0:
                    used_job_events += u

    created_jobs_this_period = 0
    for j in jobs:
        if j.get("workspace_id") == ws.get("id"):
            ca = j.get("created_at")
            if isinstance(ca, str) and len(ca) >= 7:
                # accept both Z and non-Z
                ca_period = ca[:7].replace("-", "")
                if ca_period == period:
                    created_jobs_this_period += 1

    mjq = ws.get("monthly_job_quota")
    mrq = ws.get("monthly_request_quota")
    mjq = mjq if isinstance(mjq, int) and mjq >= 0 else 0
    mrq = mrq if isinstance(mrq, int) and mrq >= 0 else 0

    quotas = {
        "period_yyyymm": period,
        "monthly_job_quota": mjq,
        "monthly_request_quota": mrq,
        "usage": {
            "jobs_created": created_jobs_this_period,
            "request_units": used_request_units,
            "job_events": used_job_events,
        },
        "remaining": {
            "jobs": None if ws.get("plan") == "enterprise" else max(0, mjq - created_jobs_this_period),
            "requests": None if ws.get("plan") == "enterprise" else max(0, mrq - used_request_units),
        },
    }

    scopes = ["jobs:read", "jobs:write", "results:read"]

    _log("ok", workspace_id=ws.get("id"), api_key_id=key_row.get("id"))

    return {
        "workspace": ws,
        "api_key": {
            "id": key_row.get("id"),
            "workspace_id": key_row.get("workspace_id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "scopes": scopes,
        "quota": quotas,
    }

