        if not isinstance(s, str) or not s.strip():
            raise ValueError("bad dt")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        return datetime.datetime.fromisoformat(ss)

    try:
        ca_after = _parse_dt(created_after)
    except ValueError:
        _log("error", workspace_id="unknown", api_key_id=None)
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time")
    try:
        ca_before = _parse_dt(created_before)
    except ValueError:
        _log("error", workspace_id="unknown", api_key_id=None)
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time")

    # Authenticate
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", workspace_id="unknown", api_key_id=key_row.get("id") if key_row else None)
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws or ws.get("status") != "active":
        _log("error", workspace_id=key_row.get("workspace_id") if key_row else "unknown", api_key_id=key_row.get("id") if key_row else None)
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Update last_used_at
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i]["last_used_at"] = now_iso
            api_keys[i]["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Decode cursor (offset-based)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", workspace_id=ws.get("id"), api_key_id=key_row.get("id"))
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad")
        except Exception:
            _log("error", workspace_id=ws.get("id"), api_key_id=key_row.get("id"))
            return _err("VALIDATION_ERROR", "Invalid cursor")

    jobs = _load("scrape_jobs.json")

    def _job_created_dt(j):
        s = j.get("created_at")
        if not isinstance(s, str) or not s:
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # Filter by workspace and optional filters
    filtered = []
    for j in jobs:
        if j.get("workspace_id") != ws.get("id"):
            continue
        if status is not None and j.get("status") != status:
            continue
        if tool is not None and j.get("tool") != tool:
            continue
        if idempotency_key is not None and j.get("idempotency_key") != idempotency_key:
            continue
        cdt = _job_created_dt(j)
        if ca_after is not None and (cdt is None or cdt < ca_after):
            continue
        if ca_before is not None and (cdt is None or cdt > ca_before):
            continue
        filtered.append(j)

    # Sort newest first by created_at then id
    filtered.sort(key=lambda x: ((x.get("created_at") or ""), (x.get("id") or "")), reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", workspace_id=ws.get("id"), api_key_id=key_row.get("id"))

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_scrape_job(api_key, job_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
