            "id": lid,
            "workspace_id": workspace_id if workspace_id is not None else "unknown",
            "api_key_id": api_key_id,
            "job_id": job_id_log,
            "tool": None,
            "units": 1,
            "unit_type": "request",
            "period_yyyymm": period,
            "created_at": now_iso,
            "updated_at": now_iso,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("usage_ledger.json", ledger)

    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", workspace_id="unknown", api_key_id=None, job_id_log=None)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(job_id, str) or not job_id.strip():
        _log("error", workspace_id="unknown", api_key_id=None, job_id_log=None)
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", workspace_id="unknown", api_key_id=key_row.get("id") if key_row else None, job_id_log=job_id)
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws or ws.get("status") != "active":
        _log("error", workspace_id=key_row.get("workspace_id") if key_row else "unknown", api_key_id=key_row.get("id") if key_row else None, job_id_log=job_id)
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Update last_used_at
    now2 = datetime.datetime.utcnow().replace(microsecond=0)
    now2_iso = now2.isoformat() + "Z"
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i]["last_used_at"] = now2_iso
            api_keys[i]["updated_at"] = now2_iso
            break
    _save("api_keys.json", api_keys)

    jobs = _load("scrape_jobs.json")
    job = None
    for j in jobs:
        if j.get("id") == job_id:
            job = j
            break

    if not job:
        _log("error", workspace_id=ws.get("id"), api_key_id=key_row.get("id"), job_id_log=job_id)
        return _err("NOT_FOUND", "Job not found")

    if job.get("workspace_id") != ws.get("id"):
        _log("error", workspace_id=ws.get("id"), api_key_id=key_row.get("id"), job_id_log=job_id)
        return _err("UNAUTHORIZED", "Job does not belong to this workspace")

    _log("ok", workspace_id=ws.get("id"), api_key_id=key_row.get("id"), job_id_log=job_id)
    return {"data": job}

def update_scrape_job(api_key, job_id, status=None, priority=None, scheduled_at=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_scrape_job"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    period = now_dt.strftime("%Y%m")

    usage = _load("usage_ledger.json")
    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")

    def _new_ledger_id():
        return f"ox_usg_{int(time.time()*1000)}_{os.getpid()}_{len(usage)+1}"

    def _log(workspace_id, api_key_id, job_id_for_log, status_str, units=1, unit_type="request", tool=None, extra=None):
        nonlocal usage
        row = {
            "id": _new_ledger_id(),
            "workspace_id": workspace_id if workspace_id is not None else "unknown",
            "api_key_id": api_key_id,
            "job_id": job_id_for_log,
            "tool": tool,
            "units": int(units),
            "unit_type": unit_type,
            "period_yyyymm": period,
            "created_at": now_iso,
            "updated_at": now_iso,
            "_endpoint": endpoint,
            "_status": status_str,
            "_latency_ms": int((time.time() - t0) * 1000),
        }
        if extra is not None:
            row["_meta"] = extra
        usage.append(row)
        _save("usage_ledger.json", usage)

    def _parse_dt_isoz(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "INVALID"
        try:
            datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return s
        except ValueError:
            return "INVALID"

    def _find_key_and_ws(api_key_value):
        # Authenticate by id OR by client-visible key material if present (never by hash).
        for k in keys if isinstance(keys, list) else []:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("id") == api_key_value or k.get("key") == api_key_value or k.get("token") == api_key_value:
                wsid = k.get("workspace_id")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsid), None)
                if ws and ws.get("status") == "active":
                    return k, ws
        return None, None

    def _allowed_transition(frm, to):
        transitions = {
            "queued": ["running", "cancelled", "expired"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": ["queued"],
            "cancelled": [],
            "expired": [],
        }
        return to in transitions.get(frm, [])

    # Validate inputs (do not log as success on invalid args)
    if not isinstance(api_key, str) or not api_key.strip():
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(job_id, str) or not job_id.strip():
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string")
    if status is not None:
        if not isinstance(status, str):
            _log("unknown", None, job_id, "error", extra={"reason": "validation"})
            return _err("VALIDATION_ERROR", "status must be a string when provided")
        if status not in ("queued", "cancelled"):
            _log("unknown", None, job_id, "error", extra={"reason": "validation"})
            return _err("VALIDATION_ERROR", "status must be one of: queued, cancelled")
    if priority is not None:
        if not isinstance(priority, int):
            _log("unknown", None, job_id, "error", extra={"reason": "validation"})
            return _err("VALIDATION_ERROR", "priority must be an integer when provided")
        if priority < 0 or priority > 100:
            _log("unknown", None, job_id, "error", extra={"reason": "validation"})
            return _err("VALIDATION_ERROR", "priority must be between 0 and 100")
    parsed_sched = _parse_dt_isoz(scheduled_at)
    if parsed_sched == "INVALID":
        _log("unknown", None, job_id, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "scheduled_at must be an ISO 8601 datetime string when provided")

    # Authenticate
    key_row, ws_row = _find_key_and_ws(api_key)
    if not key_row or not ws_row:
        _log("unknown", None, job_id, "error", extra={"reason": "auth"})
        return _err("UNAUTHORIZED", "Invalid or inactive API key, or workspace not active")

    # Locate job and authorize workspace ownership
    job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), None)
    if not job:
        _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=None, extra={"reason": "not_found"})
        return _err("NOT_FOUND", "Scrape job not found")
    if job.get("workspace_id") != ws_row.get("id"):
        _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "forbidden_workspace"})
        return _err("UNAUTHORIZED", "Job does not belong to authenticated workspace")

    # Apply updates according to lifecycle & business rules
    changed = False

    # status transition if requested
    if status is not None:
        current = job.get("status")
        if current is None:
            _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "invalid_state"})
            return _err("CONFLICT", "Job has no current status")
        if status == current:
            # Idempotent: allow returning current job (but still enforce that transition would not be illegal)
            pass
        else:
            # cancellation: only allowed from queued or running
            if status == "cancelled":
                if current not in ("queued", "running"):
                    _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"from": current, "to": status})
                    return _err("INVALID_TRANSITION", f"Cannot cancel a job from status '{current}'")
            # retry: only allowed from failed -> queued with attempt increment and attempt < max_attempts
            if status == "queued":
                if current != "failed":
                    _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"from": current, "to": status})
                    return _err("INVALID_TRANSITION", f"Retry to 'queued' is only allowed from 'failed' status (current: '{current}')")
                attempt = job.get("attempt")
                max_attempts = job.get("max_attempts")
                if not isinstance(attempt, int) or attempt < 1:
                    _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "bad_attempt"})
                    return _err("CONFLICT", "Job attempt counter is invalid")
                if not isinstance(max_attempts, int) or max_attempts < 1:
                    _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "bad_max_attempts"})
                    return _err("CONFLICT", "Job max_attempts is invalid")
                if attempt >= max_attempts:
                    _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"attempt": attempt, "max_attempts": max_attempts})
                    return _err("INVALID_TRANSITION", "Cannot retry job: attempt has reached max_attempts")
            # lifecycle transitions check (for completeness)
            if not _allowed_transition(current, status):
                _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"from": current, "to": status})
                return _err("INVALID_TRANSITION", f"Invalid status transition: {current} -> {status}")

            # enact transition
            job["status"] = status
            if status == "cancelled":
                if job.get("started_at") is None and current == "queued":
                    # leave started_at null
                    pass
                # mark finished
                job["finished_at"] = now_iso
            if status == "queued":
                # retry: increment attempt; clear error fields; clear timing fields
                job["attempt"] = int(job.get("attempt", 1)) + 1
                job["error_code"] = None
                job["error_message"] = None
                job["started_at"] = None
                job["finished_at"] = None
            changed = True

    # scheduling/priority updates: only while not finished (i.e., not in terminal states succeeded/failed/cancelled/expired)
    terminal = job.get("status") in ("succeeded", "failed", "cancelled", "expired")
    if priority is not None:
        if terminal:
            _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "terminal_update"})
            return _err("INVALID_TRANSITION", "Cannot update priority for a finished (terminal) job")
        if job.get("priority") != priority:
            job["priority"] = priority
            changed = True

    if scheduled_at is not None:
        if terminal:
            _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "terminal_update"})
            return _err("INVALID_TRANSITION", "Cannot update scheduled_at for a finished (terminal) job")
        if job.get("scheduled_at") != parsed_sched:
            job["scheduled_at"] = parsed_sched
            changed = True

    if not changed:
        # No success without effect: if request had no mutable fields or all were no-ops.
        _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "no_effect"})
        return _err("CONFLICT", "No changes applied (request had no effect)")

    job["updated_at"] = now_iso
    # best-effort link: note which key updated it
    if job.get("api_key_id") is None:
        job["api_key_id"] = key_row.get("id")

    _save("scrape_jobs.json", jobs)

    # mark key last_used_at on successful authorized mutation
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _log(ws_row.get("id"), key_row.get("id"), job_id, "ok", tool=job.get("tool"), extra={"updated": True})

    return {
        "job": job,
        "request_id": _new_ledger_id(),
    }

def list_job_results(api_key, job_id, cursor=None, limit=None, status=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Ensure request log collection exists (schema mentions usage ledger; use it as observable per-call ledger too)
    usage = _load("usage_ledger.json")
    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    results = _load("job_results.json")

    def _period_yyyymm(dtiso):
        try:
            dt = datetime.datetime.fromisoformat(dtiso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.utcnow()
        return f"{dt.year:04d}{dt.month:02d}"

    def _log(workspace_id, api_key_id, job_id_for_log, tool, units, unit_type, status_str, extra=None):
        nonlocal usage
        rid = f"usg_{int(time.time()*1000)}_{os.getpid()}_{len(usage)+1}"
        row = {
            "id": rid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": job_id_for_log,
            "tool": tool,
            "units": int(units),
            "unit_type": unit_type,
            "period_yyyymm": _period_yyyymm(now),
            "created_at": now,
            "updated_at": now,
        }
        if extra:
            row["_meta"] = extra
            row["_status"] = status_str
        else:
            row["_status"] = status_str
        usage.append(row)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(job_id, str) or not job_id.strip():
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("ready", "redacted", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: ready, redacted, deleted")

    # Authenticate: match by id OR by client-visible key value (cannot verify hash)
    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        # log unauth attempt (best-effort, no workspace)
        _log(workspace_id="unknown", api_key_id=None, job_id_for_log=None, tool=None, units=1, unit_type="request", status_str="unauthorized",
             extra={"endpoint": "list_job_results", "job_id": job_id, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_ledger.json", usage)
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    ws_id = key_row.get("workspace_id")
    ws = next((w for w in workspaces if w.get("id") == ws_id), None)
    if not ws or ws.get("status") != "active":
        _log(workspace_id=ws_id or "unknown", api_key_id=key_row.get("id"), job_id_for_log=None, tool=None, units=1, unit_type="request", status_str="unauthorized",
             extra={"endpoint": "list_job_results", "job_id": job_id, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_ledger.json", usage)
        return _err("UNAUTHORIZED", "Workspace is not active")

    job = next((j for j in jobs if j.get("id") == job_id), None)
    if not job:
        _log(workspace_id=ws_id, api_key_id=key_row.get("id"), job_id_for_log=None, tool=None, units=1, unit_type="request", status_str="not_found",
             extra={"endpoint": "list_job_results", "job_id": job_id, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_ledger.json", usage)
        return _err("NOT_FOUND", "Job not found")
    if job.get("workspace_id") != ws_id:
        _log(workspace_id=ws_id, api_key_id=key_row.get("id"), job_id_for_log=job_id, tool=job.get("tool"), units=1, unit_type="request", status_str="unauthorized",
             extra={"endpoint": "list_job_results", "job_id": job_id, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_ledger.json", usage)
        return _err("UNAUTHORIZED", "Job does not belong to this workspace")

    # Basic rate limiting: 60 requests/min per api_key_id based on usage_ledger request units (including meta logs)
    window_seconds = 60
    try:
        now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
    except Exception:
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
    recent = 0
    for u in usage:
        if u.get("api_key_id") != key_row.get("id"):
            continue
        if u.get("unit_type") != "request":
            continue
        ts = u.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += int(u.get("units") or 0)
    if recent >= 60:
        _log(workspace_id=ws_id, api_key_id=key_row.get("id"), job_id_for_log=job_id, tool=job.get("tool"), units=1, unit_type="request", status_str="rate_limited",
             extra={"endpoint": "list_job_results", "job_id": job_id, "latency_ms": int((time.time() - t0) * 1000)})
        _save("usage_ledger.json", usage)
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    # Pagination cursor: base64 JSON {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter results
    matched = [r for r in results if r.get("job_id") == job_id]
    if status is not None:
        matched = [r for r in matched if r.get("status") == status]

    # Sort by part_index asc then created_at
    def _sort_key(r):
        pi = r.get("part_index")
        if not isinstance(pi, int):
            pi = 10**9
        ca = r.get("created_at") or ""
        return (pi, ca, r.get("id") or "")
    matched.sort(key=_sort_key)

    total = len(matched)
    page = matched[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Update key last_used_at on successful auth+access
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", keys)

    # Log request usage (1 request unit)
    _log(workspace_id=ws_id, api_key_id=key_row.get("id"), job_id_for_log=job_id, tool=job.get("tool"), units=1, unit_type="request", status_str="ok",
         extra={"endpoint": "list_job_results", "cursor": cursor, "limit": limit, "filter_status": status, "latency_ms": int((time.time() - t0) * 1000)})
    _save("usage_ledger.json", usage)

    return {
        "results": page,
        "job": {"id": job.get("id"), "status": job.get("status"), "tool": job.get("tool")},
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def get_job_result(api_key, result_id, include_raw_body=None, include_parsed=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0506000" if __import__("os").path.isdir("./environment_mix/0506000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_job_result"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    period = now_dt.strftime("%Y%m")

    usage = _load("usage_ledger.json")
    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    results = _load("job_results.json")

    def _new_ledger_id():
        return f"ox_usg_{int(time.time()*1000)}_{os.getpid()}_{len(usage)+1}"

    def _log(workspace_id, api_key_id, job_id_for_log, status_str, units=1, unit_type="request", tool=None, extra=None):
        nonlocal usage
        row = {
            "id": _new_ledger_id(),
            "workspace_id": workspace_id if workspace_id is not None else "unknown",
            "api_key_id": api_key_id,
            "job_id": job_id_for_log,
            "tool": tool,
            "units": int(units),
            "unit_type": unit_type,
            "period_yyyymm": period,
            "created_at": now_iso,
            "updated_at": now_iso,
            "_endpoint": endpoint,
            "_status": status_str,
            "_latency_ms": int((time.time() - t0) * 1000),
        }
        if extra is not None:
            row["_meta"] = extra
        usage.append(row)
        _save("usage_ledger.json", usage)

    def _find_key_and_ws(api_key_value):
        for k in keys if isinstance(keys, list) else []:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("id") == api_key_value or k.get("key") == api_key_value or k.get("token") == api_key_value:
                wsid = k.get("workspace_id")
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsid), None)
                if ws and ws.get("status") == "active":
                    return k, ws
        return None, None

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(result_id, str) or not result_id.strip():
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "result_id must be a non-empty string")
    if include_raw_body is None:
        include_raw_body = True
    if include_parsed is None:
        include_parsed = True
    if not isinstance(include_raw_body, bool):
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "include_raw_body must be a boolean when provided")
    if not isinstance(include_parsed, bool):
        _log("unknown", None, None, "error", extra={"reason": "validation"})
        return _err("VALIDATION_ERROR", "include_parsed must be a boolean when provided")

    # Authenticate
    key_row, ws_row = _find_key_and_ws(api_key)
    if not key_row or not ws_row:
        _log("unknown", None, None, "error", extra={"reason": "auth"})
        return _err("UNAUTHORIZED", "Invalid or inactive API key, or workspace not active")

    # Find result
    res = next((r for r in results if isinstance(r, dict) and r.get("id") == result_id), None)
    if not res:
        _log(ws_row.get("id"), key_row.get("id"), None, "ok", units=1, unit_type="request", extra={"found": False})
        return {"result": None, "found": False, "request_id": _new_ledger_id()}

    job_id = res.get("job_id")
    job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), None)
    if not job:
        _log(ws_row.get("id"), key_row.get("id"), job_id, "error", extra={"reason": "fk_missing"})
        return _err("NOT_FOUND", "Owning job for this result was not found")

    if job.get("workspace_id") != ws_row.get("id"):
        _log(ws_row.get("id"), key_row.get("id"), job_id, "error", tool=job.get("tool"), extra={"reason": "forbidden_workspace"})
        return _err("UNAUTHORIZED", "Result does not belong to authenticated workspace")

    # Apply redaction/deletion rules
    out = dict(res)  # copy
    rstatus = out.get("status")
    if rstatus in ("redacted", "deleted"):
        out["raw_body"] = None
        if rstatus == "deleted":
            out["bytes"] = 0
        out["parsed"] = None

    # Apply include flags and parse_content rule
    if not include_raw_body:
        out["raw_body"] = None

    parse_content = job.get("parse_content")
    if parse_content is False:
        out["parsed"] = None
    if not include_parsed:
        out["parsed"] = None

    # Successful read logging + key last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _log(ws_row.get("id"), key_row.get("id"), job_id, "ok", units=1, unit_type="request", tool=job.get("tool"), extra={"result_status": rstatus})

    return {
        "result": out,
        "job": {"id": job.get("id"), "status": job.get("status"), "tool": job.get("tool")},
        "request_id": _new_ledger_id(),
    }
